// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        BankActor bank = new BankActor();
        vm.startPrank(address(bank));
        c.airDrop();
        vm.stopPrank();
        assertEq(c.tokenBalance(address(bank)), 20, "tokenBalance must be 20 after airdrop");
    }
}

contract BankActor {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
